#include "flight/sanity_sensor.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
uint64_t fake_fc_now;
int main(int argc,char**argv){double frequency=argc>1?atof(argv[1]):5;fake_fc_now=UINT64_C(0xfffff000);uint64_t start=fake_fc_now;se_clock_packet request={.nonce=42},reply;sanitySensorClock(&request,&reply);assert(reply.epoch==42);unsigned received=0;double squares=0;unsigned samples=0;uint32_t lastgyro=0;for(unsigned i=1;i<=160000;i++){fake_fc_now=start+i*125ULL;float gyro[3]={(float)(sin(2*3.141592653589793*frequency*i/8000.0)*57.29577951308232),0,0};sanitySensorGyro((uint32_t)fake_fc_now,gyro,true,true,2,125);if(i%8==0){float acceleration[3]={0,0,256};/* AccDRDYslightlyolder thanthisgyro(andoccasionallylastemit). */sanitySensorAccel((uint32_t)(fake_fc_now-375),acceleration,256,true,true,2,125);}uint8_t bytes[76];while(sanitySensorPop(bytes)){se_sensor_packet p;assert(se_sensor_decode(bytes,76,&p));assert(p.epoch==42&&p.flags==15&&p.gyro_delay_us==15915&&p.accel_delay_us==15915);if(received)assert((int32_t)(p.gyro_us-lastgyro)>0);lastgyro=p.gyro_us;assert(abs((int32_t)(p.gyro_us-p.accel_us))<2000);assert(fabs(p.accel[2]-9.80665)<1e-5);received++;if(i>8000){squares+=p.gyro[0]*p.gyro[0];samples++;}}}assert(received>=3998&&received<=4000);for(unsigned i=1;i<=2000;i++){fake_fc_now+=125;float gyro[3]={0},accel[3]={0,0,256};sanitySensorGyro((uint32_t)fake_fc_now,gyro,true,true,2,125);if(i%8==0)sanitySensorAccel((uint32_t)(fake_fc_now-375),accel,256,true,true,2,125);}uint8_t bytes[76];uint32_t drops=0;unsigned queued=0;while(sanitySensorPop(bytes)){se_sensor_packet p;assert(se_sensor_decode(bytes,76,&p));drops=p.dropped;queued++;}assert(queued==8&&drops>0);double gain=sqrt(squares/samples)*sqrt(2);if(frequency>=100)assert(gain<.025);printf("{\"frequency_hz\":%.3f,\"gain\":%.9g,\"samples\":%u,\"drop_oldest\":%u,\"wrap_and_interleaved_acquisition\":true}\n",frequency,gain,received,drops);return 0;}
